content.content:
Oi! Sou o dono da Pousada Maré Alta, uma pousada pequena no litoral. O sistema de reservas que a gente usa está nesta pasta. Ele funciona bem, e quem fez deixou um README explicando como ele é.

Preciso de uma mudança, que explico abaixo.

Revimos os preços da alta temporada, e mudaram duas coisas.

A primeira é que a noite de temporada passa a custar 25% a mais, e não 20% como hoje. Um standard numa noite de temporada, que hoje sai R$ 299,88, vai sair R$ 312,38.

A segunda é que a semana da Páscoa também vira alta temporada: as noites do domingo de Ramos até o domingo de Páscoa, contando os dois domingos. Em 2027 são as noites de 21/03 a 28/03, e em 2028, as de 09/04 a 16/04. Pode deixar só esses dois anos, eu te passo os seguintes quando chegar a hora. O resto fica como está, de 15 de dezembro ao fim de fevereiro e o mês de julho inteiro.

A gente já pensou em ter um acréscimo diferente para cada temporada, mas por enquanto é o mesmo para todas.

Tudo o que funciona hoje tem que continuar funcionando, menos o que eu pedi para mudar. Quando terminar, o `mvn verify` precisa passar. Não precisa me perguntar nada: se alguma coisa não estiver clara, decida do jeito que achar mais sensato e siga em frente.
----
diff --git a/src/main/java/hotel/reservations/PriceCalculator.java b/src/main/java/hotel/reservations/PriceCalculator.java
index bd53dba..e8cf5d0 100644
--- a/src/main/java/hotel/reservations/PriceCalculator.java
+++ b/src/main/java/hotel/reservations/PriceCalculator.java
@@ -13,7 +13,7 @@ import java.time.Month;
  */
 public final class PriceCalculator {

-    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
+    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
     static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");

     public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
@@ -38,13 +38,32 @@ public final class PriceCalculator {
         return cents(nightlyRate);
     }

-    /** High season: from December 15 to the end of February, and the whole of July. */
+    /** High season: from December 15 to the end of February, the whole of July, and Easter week. */
     static boolean isHighSeason(LocalDate date) {
         Month month = date.getMonth();
-        return month == Month.JANUARY
+        if (month == Month.JANUARY
                 || month == Month.FEBRUARY
                 || month == Month.JULY
-                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
+                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)) {
+            return true;
+        }
+        if (month == Month.MARCH || month == Month.APRIL) {
+            return isEasterSeason(date);
+        }
+        return false;
+    }
+
+    private static boolean isEasterSeason(LocalDate date) {
+        int year = date.getYear();
+        int month = date.getMonthValue();
+        int day = date.getDayOfMonth();
+
+        if (year == 2027) {
+            return (month == 3 && day >= 21 && day <= 28);
+        } else if (year == 2028) {
+            return (month == 4 && day >= 9 && day <= 16);
+        }
+        return false;
     }

     static BigDecimal cents(BigDecimal value) {
diff --git a/src/test/java/hotel/reservations/PriceCalculatorTest.java b/src/test/java/hotel/reservations/PriceCalculatorTest.java
index 2c43e72..7ba4ece 100644
--- a/src/test/java/hotel/reservations/PriceCalculatorTest.java
+++ b/src/test/java/hotel/reservations/PriceCalculatorTest.java
@@ -32,8 +32,8 @@ class PriceCalculatorTest {
         Price price = calculator.calculate(
                 standardRoom, LocalDate.of(2027, 12, 14), LocalDate.of(2027, 12, 16), RatePlan.STANDARD);

-        // December 14: 249.90; December 15: 249.90 + 20% = 299.88
-        assertEquals(new BigDecimal("549.78"), price.total());
+        // December 14: 249.90; December 15: 249.90 + 25% = 312.38
+        assertEquals(new BigDecimal("562.28"), price.total());
     }

     @Test
@@ -41,8 +41,8 @@ class PriceCalculatorTest {
         Price price = calculator.calculate(
                 standardRoom, LocalDate.of(2028, 2, 29), LocalDate.of(2028, 3, 2), RatePlan.STANDARD);

-        // February 29 (leap year): 299.88; March 1: 249.90
-        assertEquals(new BigDecimal("549.78"), price.total());
+        // February 29 (leap year): 312.38; March 1: 249.90
+        assertEquals(new BigDecimal("562.28"), price.total());
     }

     @Test
@@ -53,6 +53,32 @@ class PriceCalculatorTest {
         assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 8, 1)));
     }

+    @Test
+    void easterWeekIsHighSeasonIn2027() {
+        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 20)));
+        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 21)));
+        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 28)));
+        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 29)));
+    }
+
+    @Test
+    void easterWeekIsHighSeasonIn2028() {
+        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 8)));
+        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 9)));
+        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 16)));
+        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 17)));
+    }
+
+    @Test
+    void easterWeekHighSeasonPrice() {
+        Price price = calculator.calculate(
+                standardRoom, LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 23), RatePlan.STANDARD);
+
+        // Both nights in Easter week: 249.90 + 25% = 312.38 each
+        assertEquals(2, price.nights());
+        assertEquals(new BigDecimal("624.76"), price.total());
+    }
+
     @Test
     void nonRefundableTakes15PercentOffRoundingHalfEven() {
         Price price = calculator.calculate(
@@ -68,9 +94,9 @@ class PriceCalculatorTest {
         Price price = calculator.calculate(
                 suite, LocalDate.of(2027, 1, 5), LocalDate.of(2027, 1, 9), RatePlan.NON_REFUNDABLE);

-        // 4 nights of 579.90 + 20% = 695.88 each
-        assertEquals(new BigDecimal("2783.52"), price.subtotal());
-        assertEquals(new BigDecimal("417.53"), price.discount());
-        assertEquals(new BigDecimal("2365.99"), price.total());
+        // 4 nights of 579.90 + 25% = 724.88 each
+        assertEquals(new BigDecimal("2899.52"), price.subtotal());
+        assertEquals(new BigDecimal("434.93"), price.discount());
+        assertEquals(new BigDecimal("2464.59"), price.total());
     }
 }
diff --git a/src/test/java/hotel/web/HttpApiTest.java b/src/test/java/hotel/web/HttpApiTest.java
index f9a3f6f..de2f14d 100644
--- a/src/test/java/hotel/web/HttpApiTest.java
+++ b/src/test/java/hotel/web/HttpApiTest.java
@@ -74,7 +74,7 @@ class HttpApiTest {
         long id = reservation.get("id").asLong();
         assertEquals("PENDING", reservation.get("status").asText());
         assertEquals("2027-07-10", reservation.get("checkIn").asText());
-        assertEquals(935.76, reservation.get("total").asDouble());
+        assertEquals(974.76, reservation.get("total").asDouble());

         assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
         JsonNode messages = json.readTree(get("/messages").body());
@@ -115,7 +115,7 @@ class HttpApiTest {
         assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
         assertTrue(occupancy.body().endsWith("total,1/5\n"));

-        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,935.76\n"));
+        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,974.76\n"));
         assertEquals(400, get("/reports/revenue?month=july").statusCode());
         assertEquals(400, get("/reports/occupancy").statusCode());
     }
