313	/**
314	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
315	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
316	 * src/main/resources/db/migration.
317	 */
318	public final class Database implements AutoCloseable {
319	
320	    private final HikariDataSource dataSource;
321	
322	    public Database(Map<String, String> environment) {
323	        String url = environment.get("DB_URL");
324	        if (url == null || url.isBlank()) {
325	            throw new IllegalStateException("DB_URL is not set: it must hold the PostgreSQL address");
326	        }
327	        HikariConfig config = new HikariConfig();
328	        config.setJdbcUrl(url);
329	        config.setUsername(environment.get("DB_USER"));
330	        config.setPassword(environment.get("DB_PASSWORD"));
331	        this.dataSource = new HikariDataSource(config);
332	        Flyway.configure().dataSource(dataSource).load().migrate();
333	    }
334	
335	    public DataSource dataSource() {
336	        return dataSource;
337	    }
338	
