160	    private BigDecimal amountPaid;
161	    private BigDecimal refund;
162	
163	    Reservation(long id, NewReservation request, Price price) {
164	        this(id, request, price, ReservationStatus.PENDING, PriceCalculator.cents(BigDecimal.ZERO), null);
165	    }
166	
167	    Reservation(
168	            long id,
169	            NewReservation request,
170	            Price price,
171	            ReservationStatus status,
172	            BigDecimal amountPaid,
173	            BigDecimal refund) {
174	        this.id = id;
175	        this.roomNumber = request.roomNumber();
176	        this.guest = request.guest();
177	        this.checkIn = request.checkIn();
178	        this.checkOut = request.checkOut();
179	        this.guests = request.guests();
180	        this.ratePlan = request.ratePlan();
181	        this.price = price;
182	        this.status = status;
183	        this.amountPaid = amountPaid;
184	        this.refund = refund;
185	    }
186	
187	    public long id() {
188	        return id;
189	    }
190	
191	    public int roomNumber() {
192	        return roomNumber;
193	    }
194	
195	    public Guest guest() {
196	        return guest;
197	    }
198	
199	    public LocalDate checkIn() {
200	        return checkIn;
201	    }
202	
203	    public LocalDate checkOut() {
204	        return checkOut;
205	    }
206	
207	    public int guests() {
208	        return guests;
209	    }
210	
211	    public RatePlan ratePlan() {
212	        return ratePlan;
213	    }
214	
215	    public Price price() {
216	        return price;
217	    }
218	
219	    public ReservationStatus status() {
220	        return status;
221	    }
222	
223	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
224	    public BigDecimal amountPaid() {
225	        return amountPaid;
226	    }
227	
228	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
229	    public BigDecimal refund() {
230	        return refund;
231	    }
232	
233	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
234	    public boolean isPaid() {
235	        return status == ReservationStatus.CONFIRMED
236	                || status == ReservationStatus.CHECKED_IN
237	                || status == ReservationStatus.CHECKED_OUT;
238	    }
239	
240	    /** The money the inn keeps from this reservation. */
241	    public BigDecimal amountKept() {
242	        return refund == null ? amountPaid : amountPaid.subtract(refund);
243	    }
244	
245	    void changeStatus(ReservationStatus newStatus) {
246	        this.status = newStatus;
247	    }
248	
249	    void confirmPayment() {
250	        this.status = ReservationStatus.CONFIRMED;
251	        this.amountPaid = price.total();
252	    }
253	
254	    void cancel(BigDecimal refundAmount) {
255	        this.status = ReservationStatus.CANCELLED;
256	        this.refund = refundAmount;
257	    }
