353	    (101, 'STANDARD', 2, 249.90),
354	    (102, 'STANDARD', 2, 249.90),
355	    (201, 'DELUXE', 3, 389.90),
356	    (202, 'DELUXE', 3, 389.90),
357	    (301, 'SUITE', 4, 579.90);
358	
359	-- btree_gist lets one constraint compare the room number (equality) and the nights (overlap) together.
360	CREATE EXTENSION IF NOT EXISTS btree_gist;
361	
362	CREATE TABLE reservations (
363	    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
364	    room_number integer NOT NULL REFERENCES rooms (number),
365	    guest_name  text NOT NULL,
366	    guest_email text NOT NULL,
367	    guest_cpf   text NOT NULL,
368	    check_in    date NOT NULL,
369	    check_out   date NOT NULL,
370	    guests      integer NOT NULL CHECK (guests >= 1),
371	    rate_plan   text NOT NULL,
372	    nights      integer NOT NULL,
373	    subtotal    numeric(10, 2) NOT NULL,
374	    discount    numeric(10, 2) NOT NULL,
375	    total       numeric(10, 2) NOT NULL,
376	    status      text NOT NULL,
377	    amount_paid numeric(10, 2) NOT NULL,
378	    refund      numeric(10, 2),
379	    CHECK (check_out > check_in),
380	    -- a room is never booked twice for the same night, even when two requests arrive at the same time
381	    CONSTRAINT reservations_no_double_booking
382	        EXCLUDE USING gist (room_number WITH =, daterange(check_in, check_out) WITH &&)
383	        WHERE (status <> 'CANCELLED')
384	);
385	
386	-- every message the inn sent, so the front desk can check what each guest received
387	CREATE TABLE messages (
388	    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
389	    channel   text NOT NULL,
390	    recipient text NOT NULL,
391	    subject   text NOT NULL,
392	    body      text NOT NULL
393	);

